//! TypeScript binding generation.
//!
//! `cargo test -p orkestr-protocol export_bindings` runs every ts-rs
//! auto-generated `export_bindings_*` test of this crate **and** the explicit
//! [`export_bindings`] test below, which
//! 1. exports every domain entity (they live in another crate, so their own
//!    auto tests do not run here), and
//! 2. writes `methods.ts` — the typed `Methods` map generated from
//!    [`crate::methods::registry`].
//!
//! Output dir: `TS_RS_EXPORT_DIR` (set in `.cargo/config.toml` to
//! `packages/protocol/src/generated`).

use std::fmt::Write as _;
use std::path::Path;

use ts_rs::{Config, TS};

use crate::methods::registry;

fn export_domain(cfg: &Config) {
    use orkestr_domain::*;
    macro_rules! all {
        ($($t:ty),* $(,)?) => { $( <$t as TS>::export_all(cfg).expect(stringify!($t)); )* };
    }
    all!(
        User,
        Device,
        Node,
        Project,
        Repository,
        Workspace,
        WorkspaceSnapshot,
        Provider,
        ProviderCredentialReference,
        Model,
        AgentTemplate,
        AgentInstance,
        AgentTeam,
        Task,
        TaskDependency,
        Execution,
        ToolCall,
        Approval,
        MemoryItem,
        KnowledgeSource,
        Decision,
        Environment,
        Deployment,
        SecretReference,
        UsageRecord,
        AuditEvent,
        Plugin,
        McpServer,
        Notification,
        AgentState,
        Capability,
        ApprovalMode,
        TaskStatus,
        TaskPriority,
        PermissionRule,
        ProviderHealth,
        AuthState,
        Budget,
        UsageSummary,
        ModelRef,
        RiskLevel,
        Actor,
        SessionId,
        CorrelationId,
        TerminalId,
        EventId,
    );
}

fn export_protocol(cfg: &Config) {
    use crate::event::*;
    use crate::frames::*;
    use crate::ui_config::*;
    macro_rules! all {
        ($($t:ty),* $(,)?) => { $( <$t as TS>::export_all(cfg).expect(stringify!($t)); )* };
    }
    all!(
        ClientFrame,
        ServerFrame,
        ResFrame,
        AuthResult,
        SubResult,
        ClientInfo,
        crate::RpcError,
        crate::RpcErrorCode,
        Event,
        EventKind,
        UiConfig,
        UiConfigIssue,
        StopReason,
        LogLevel,
        EmergencyScope,
        RollbackScope,
        FileChangeKind,
        MessageRole,
    );
}

fn module_path(path: &Path) -> String {
    let s = path.with_extension("").to_string_lossy().replace('\\', "/");
    format!("./{s}")
}

fn write_methods_ts(cfg: &Config) {
    let methods = registry();
    let mut imports = std::collections::BTreeMap::<String, String>::new();
    let mut body = String::new();
    for m in &methods {
        (m.export)(cfg).expect(m.name);
        for (name, path) in [((m.params_ts)(cfg), (m.params_path)()), ((m.result_ts)(cfg), (m.result_path)())] {
            if let Some(path) = path {
                imports.insert(name, module_path(&path));
            }
        }
        let _ = writeln!(body, "  \"{}\": [{}, {}];", m.name, (m.params_ts)(cfg), (m.result_ts)(cfg));
    }
    let mut out = String::from(
        "// This file was generated by orkestr-protocol (export_bindings). Do not edit this file manually.\n",
    );
    for (name, path) in &imports {
        let _ = writeln!(out, "import type {{ {name} }} from \"{path}\";");
    }
    out.push_str("\n/** Typed RPC method map: `\"area.verb\": [Params, Result]`. */\nexport type Methods = {\n");
    out.push_str(&body);
    out.push_str("};\n\n/** All implemented method names. */\nexport const METHOD_NAMES = [\n");
    for m in &methods {
        let _ = writeln!(out, "  \"{}\",", m.name);
    }
    out.push_str("] as const;\n\n");
    let _ = writeln!(
        out,
        "/** Wire protocol version (see orkestr-protocol PROTOCOL_VERSION). */\nexport const PROTOCOL_VERSION = {};",
        crate::PROTOCOL_VERSION
    );
    let _ = writeln!(
        out,
        "\n/** All event kind names, in declaration order. */\nexport const EVENT_KINDS = [\n{}] as const;",
        crate::event::EventKind::NAMES.iter().map(|k| format!("  \"{k}\",\n")).collect::<String>()
    );
    let _ = writeln!(
        out,
        "\n/** UI config schema version (see orkestr-protocol ui_config). */\nexport const UI_CONFIG_SCHEMA_VERSION = {};",
        crate::ui_config::UI_CONFIG_SCHEMA_VERSION
    );
    let dir = cfg.out_dir();
    std::fs::create_dir_all(dir).expect("create export dir");
    std::fs::write(dir.join("methods.ts"), out).expect("write methods.ts");
}

#[test]
fn export_bindings() {
    let cfg = Config::from_env();
    export_domain(&cfg);
    export_protocol(&cfg);
    write_methods_ts(&cfg);
}
